<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),properties=ref<any[]>([]),tenants=ref<any[]>([]),showModal=ref(false),error=ref(''),form=ref({property_id:'',tenant_id:'',start_date:'',end_date:'',monthly_rent:0,deposit:0,occupants:[]});const activeProperties=computed(()=>properties.value.filter(x=>x.Status==='available'));async function load(){const[l,p,t]=await Promise.all([api.get('/leases',{params:{page:1,page_size:100}}),api.get('/properties',{params:{page:1,page_size:100}}),api.get('/tenants',{params:{page:1,page_size:100,status:'active'}})]);items.value=l.data.items||[];properties.value=p.data.items||[];tenants.value=t.data.items||[]}async function add(){error.value='';try{await api.post('/leases',form.value);showModal.value=false;await load()}catch(e:any){error.value=e.response?.data?.error?.message||'创建租约失败'}}async function transition(id:string,status:string){await api.post(`/leases/${id}/transition`,{status,reason:'管理后台状态操作'});await load()}function propertyName(id:string){const x=properties.value.find(v=>v.ID===id);return x?`${x.Building} ${x.Room}`:id.slice(0,8)}function tenantName(id:string){return tenants.value.find(v=>v.ID===id)?.Name||id.slice(0,8)}onMounted(load)</script><template><div class="page"><div class="page-title"><div><h1>租约合同</h1><p>创建租约、校验租期冲突并管理合同状态和续租版本</p></div><button class="primary-button" @click="showModal=true">＋ 创建租约</button></div><div class="stat-grid"><div class="stat-card"><span>全部租约</span><strong>{{items.length}}</strong></div><div class="stat-card"><span>生效中</span><strong>{{items.filter(x=>x.Status==='active').length}}</strong></div><div class="stat-card"><span>待审核</span><strong>{{items.filter(x=>x.Status==='pending').length}}</strong></div><div class="stat-card"><span>退租处理中</span><strong>{{items.filter(x=>x.Status==='terminating').length}}</strong></div></div><section class="card"><table v-if="items.length" class="data-table"><thead><tr><th>房源</th><th>主租客</th><th>租期</th><th>月租 / 押金</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td><strong>{{propertyName(x.PropertyID)}}</strong></td><td>{{tenantName(x.TenantID)}}</td><td>{{String(x.StartDate).slice(0,10)}} 至 {{String(x.EndDate).slice(0,10)}}</td><td>{{x.MonthlyRent}} / {{x.Deposit}}</td><td><span class="status-badge" :class="x.Status">{{x.Status}}</span></td><td><div class="action-group"><button v-if="x.Status==='draft'" class="secondary-button" @click="transition(x.ID,'pending')">提交审核</button><button v-if="x.Status==='pending'" class="primary-button" @click="transition(x.ID,'active')">确认生效</button><button v-if="x.Status==='active'" class="danger-button" @click="transition(x.ID,'terminating')">发起退租</button></div></td></tr></tbody></table><div v-else class="empty-state"><b>暂无租约合同</b><span>创建租约时系统会自动检查时间重叠</span></div></section><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal"><div class="modal-header"><div><h3>创建租约</h3><small>仅展示当前可租房源和可签约租客</small></div><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>房源 *</span><select v-model="form.property_id"><option value="">请选择房源</option><option v-for="x in activeProperties" :key="x.ID" :value="x.ID">{{x.Building}} · {{x.Room}}</option></select></label><label><span>主租客 *</span><select v-model="form.tenant_id"><option value="">请选择租客</option><option v-for="x in tenants" :key="x.ID" :value="x.ID">{{x.Name}} · {{x.Phone}}</option></select></label><label><span>租期开始 *</span><input v-model="form.start_date" type="date"></label><label><span>租期结束 *</span><input v-model="form.end_date" type="date"></label><label><span>月租金额 *</span><input v-model.number="form.monthly_rent" type="number" min="1" placeholder="最小货币单位"></label><label><span>押金金额</span><input v-model.number="form.deposit" type="number" min="0" placeholder="最小货币单位"></label></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" :disabled="!form.property_id||!form.tenant_id||!form.start_date||!form.end_date" @click="add">确认创建</button></div></div></div></div></template>